<script lang="ts">
 import {databaseState,command} from '$lib/database/store';import {host,port,usersFor} from '$lib/database/model';import CreateDatabase from './CreateDatabase.svelte';export let projectId:string;let chosen='',showCreate=false,error='';$: linked=$databaseState.databases.find(d=>d.project===projectId);$: available=$databaseState.databases.filter(d=>!d.project);function run(fn:()=>void){try{error='';fn();}catch(e){error=e instanceof Error?e.message:'Database connection failed.';}}
</script>
<div class="stack"><section class="card stack"><div><h3>Project database</h3><p class="subtitle">Connect an existing database when your application needs it. Your application can also use an external database.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if linked}<div class="row between wrap"><div><a class="link-btn" href={'/databases/'+linked.id}>{linked.name}</a><small style="display:block">{linked.engine} · {usersFor($databaseState,linked.id).length} user(s)</small></div><button class="btn secondary" on:click={()=>run(()=>{if(linked)command({type:'link',database:linked.id,project:null});})}>Disconnect database</button></div><div class="summary-list"><div><span>Host</span><strong>{host(linked.engine)}</strong></div><div><span>Port</span><strong>{port(linked.engine)}</strong></div></div><small>Association only. Configure your application’s actual credentials and environment variables separately.</small>{:else}<form class="native-inline" on:submit|preventDefault={()=>run(()=>{command({type:'link',database:chosen,project:projectId});chosen='';showCreate=false;})}><label class="field grow">Available database<select required bind:value={chosen}><option value="">Select existing database</option>{#each available as d}<option value={d.id}>{d.name} · {d.engine}</option>{/each}</select></label><button class="btn primary" type="submit" disabled={!chosen}>Connect database</button></form><div><button class="btn secondary" on:click={()=>showCreate=!showCreate}>{showCreate?'Hide creation form':'Create database'}</button></div>{/if}</section>{#if showCreate&&!linked}<CreateDatabase linkedProject={projectId}/>{:else if showCreate&&linked}<p class="subtitle">Database created. Manage its users and credentials from the database page.</p>{/if}</div>
